import sys
from collections import defaultdict

def mod_pow(a, e, mod):
    res = 1
    while e:
        if e & 1:
            res = res * a % mod
        a = a * a % mod
        e >>= 1
    return res

def main():
    a, b, p, x = map(int, sys.stdin.readline().split())

    # Precompute discrete log table for a^k mod p
    # Since p is prime and 1 <= a < p, a is invertible; order divides p-1
    log_table = {}
    cur = 1
    for k in range(p - 1):
        if cur not in log_table:
            log_table[cur] = k
        cur = cur * a % p

    # Precompute count of t in [0, p-1] with t ≡ n mod p and n a^n ≡ b (mod p)
    cnt = [0] * p
    for t in range(p):
        # Need a^t * a^k ≡ b  => a^k ≡ b * a^{-t}
        inv_at = mod_pow(a, (p - 1 - t) % (p - 1), p)
        target = b * inv_at % p
        if target in log_table:
            k = log_table[target]
            n = t + k * p
            if n % p == t and n * mod_pow(a, n, p) % p == b % p:
                cnt[t] += 1

    # Count n in [1, x] by residue class t = n mod p
    total = 0
    for t in range(p):
        if cnt[t] == 0:
            continue
        # n = t + m*p, n >= 1
        if t == 0:
            first = p
        else:
            first = t
        if first > x:
            continue
        max_m = (x - first) // p
        total += cnt[t] * (max_m + 1)

    print(total)

if __name__ == "__main__":
    main()

import sys
import math

def mod_pow(a, e, mod):
    res = 1
    a %= mod
    while e > 0:
        if e & 1:
            res = res * a % mod
        a = a * a % mod
        e >>= 1
    return res

def mod_inv(a, mod):
    return mod_pow(a, mod - 2, mod)

def baby_step_giant_step(a, p):
    # returns dict: value -> smallest exponent k with a^k = value
    m = int(math.isqrt(p)) + 1
    table = {}
    cur = 1
    for j in range(m):
        if cur not in table:
            table[cur] = j
        cur = cur * a % p
    factor = mod_inv(mod_pow(a, m, p), p)
    cur = 1
    for i in range(m + 1):
        if cur in table:
            j = table[cur]
            k = i * m + j
            if k < p - 1:
                # store minimal exponent
                val = mod_pow(a, k, p)
                if val not in table or k < table[val]:
                    table[val] = k
        cur = cur * factor % p
    return table

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    a, b, p, x = map(int, data)
    phi = p - 1
    # precompute discrete log table: value -> exponent k with a^k = value
    log_table = baby_step_giant_step(a, p)

    # precompute a^t for t in [0, phi-1]
    pow_a = [1] * phi
    for t in range(1, phi):
        pow_a[t] = pow_a[t - 1] * a % p

    inv_a = mod_inv(a, p)

    ans = 0
    for t in range(phi):
        val = b * inv_a % p
        val = val * pow_a[t] % p
        if val not in log_table:
            continue
        k = log_table[val]
        if k > phi - 1:
            continue
        n0 = k + 1
        if n0 <= 0:
            continue
        if n0 > x:
            continue
        # n ≡ n0 (mod phi)
        if n0 < 1:
            n0 += ((1 - n0 + phi - 1) // phi) * phi
        if n0 > x:
            continue
        cnt = (x - n0) // phi + 1
        ans += cnt

    print(ans)

if __name__ == "__main__":
    main()
